    h,w=len(g),len(g[0]); R=[]
    for rr in range(h):
        for cc in range(w):
            for r2 in range(rr+1,h):
                for c2 in range(cc+1,w):
                    inside=True
                    for a in range(rr,r2+1):
                        for b in range(cc,c2+1):
                            if g[a][b]!=0: inside=False; break
                        if not inside: break
                    if not inside: continue
                    up=(rr==0) or (all(g[rr-1][b]==0 for b in range(cc,c2+1)))
                    dn=(r2+1>=h) or (all(g[r2+1][b]!=0 for b in range(cc,c2+1)))
                    lf=(cc==0) or (all(g[a][cc-1]==0 for a in range(rr,r2+1)))
                    rt=(c2+1>=w) or (all(g[a][c2+1]==0 for a in range(rr,r2+1)))
                    if up and dn and lf and rt: R.append((rr,r2,cc,c2))
    return R
g=G['Demo pair 2 input']
out=[r[:] for r in g]
for rr,r2,cc,c2 in mrects(g):
    for b in range(max(0,cc-1),min(len(g[0]),c2+2)):
        for a in (rr-1,r2+1):
            if 0<=a<len(g): out[a][b]=3
    for a in range(max(0,rr-1),min(len(g),r2+2)):
        for b in (cc-1,c2+1):
            if 0<=b<len(g[0]): out[a][b]=3
mm=[(i,j,out[i][j],G['Demo pair 2 output'][i][j]) for i in range(len(out)) for j in range(len(out[0])) if out[i][j]!=G['Demo pair 2 output'][i][j]]
